pub fn new(
    slug: impl Into<String>,
    endpoint: impl Into<String>,
    api_key: impl Into<String>,
    api_style: SttApiStyle,
) -> Self {
    let endpoint: String = endpoint.into();
    Self {
        slug: slug.into(),
        endpoint: endpoint.clone(),
        api_style,
        client: ExternalSttClient::new(
            reqwest::Client::new(),
            api_key.into(),
            api_style,
        ),
    }
}
